aire/universe/core.py:
"""AIRE U0 Universal Core.

U0 establishes a solver-independent representation of a deterministic world:
identity, 3-D space, global time, persistent entities, immutable laws,
events/causality, global state, and a controlled world-step operation.

The core intentionally does not implement chemistry, biology, agents, or
specialized CFD. Existing AIRE physics solvers can be attached above this
layer in later roadmap phases.
"""
from __future__ import annotations

from dataclasses import dataclass, field, replace
from types import MappingProxyType
from typing import Any, Callable, Mapping
import hashlib
import json
import math
import uuid
import numpy as np


_EPS = 1e-15


def _finite_vec3(value: Any, name: str) -> np.ndarray:
    x = np.asarray(value, dtype=float).reshape(-1)
    if x.shape != (3,) or not np.isfinite(x).all():
        raise ValueError(f"{name} must be a finite 3-vector")
    x = x.copy()
    x.setflags(write=False)
    return x


@dataclass(frozen=True)
class WorldIdentity:
    """Stable identity and lineage metadata for a world instance."""
    world_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    parent_world_id: str | None = None
    seed: int = 0
    schema_version: str = "U0.1"

    def __post_init__(self) -> None:
        if not self.world_id or not isinstance(self.world_id, str):
            raise ValueError("world_id must be a non-empty string")
        if self.parent_world_id == self.world_id:
            raise ValueError("a world cannot be its own parent")
        if int(self.seed) != self.seed:
            raise ValueError("seed must be an integer")
        object.__setattr__(self, "seed", int(self.seed))


@dataclass(frozen=True)
class Space3D:
    """Cartesian world-space contract."""
    origin: np.ndarray = field(default_factory=lambda: np.zeros(3))
    bounds_min: np.ndarray | None = None
    bounds_max: np.ndarray | None = None

    def __post_init__(self) -> None:
        origin = _finite_vec3(self.origin, "origin")
        bmin = None if self.bounds_min is None else _finite_vec3(self.bounds_min, "bounds_min")
        bmax = None if self.bounds_max is None else _finite_vec3(self.bounds_max, "bounds_max")
        if (bmin is None) != (bmax is None):
            raise ValueError("bounds_min and bounds_max must be supplied together")
        if bmin is not None and np.any(bmax <= bmin):
            raise ValueError("bounds_max must be strictly greater than bounds_min")
        object.__setattr__(self, "origin", origin)
        object.__setattr__(self, "bounds_min", bmin)
        object.__setattr__(self, "bounds_max", bmax)

    def contains(self, position: Any) -> bool:
        p = np.asarray(position, dtype=float).reshape(-1)
        if p.shape != (3,) or not np.isfinite(p).all():
            return False
        if self.bounds_min is None:
            return True
        return bool(np.all(p >= self.bounds_min) and np.all(p <= self.bounds_max))

    def to_local(self, position: Any) -> np.ndarray:
        return _finite_vec3(np.asarray(position, dtype=float) - self.origin, "local_position")

    def to_world(self, local_position: Any) -> np.ndarray:
        return _finite_vec3(np.asarray(local_position, dtype=float) + self.origin, "world_position")

    def validate(self) -> None:
        if self.bounds_min is not None and not self.contains(self.origin):
            raise ValueError("space origin must lie inside bounded world space")


@dataclass(frozen=True)
class SimulationClock:
    """Deterministic global simulation clock."""
    time: float = 0.0
    step_index: int = 0
    dt: float = 1e-3

    def __post_init__(self) -> None:
        if not math.isfinite(float(self.time)):
            raise ValueError("time must be finite")
        if int(self.step_index) != self.step_index or self.step_index < 0:
            raise ValueError("step_index must be a non-negative integer")
        if not math.isfinite(float(self.dt)) or self.dt <= 0:
            raise ValueError("dt must be finite and > 0")
        object.__setattr__(self, "time", float(self.time))
        object.__setattr__(self, "step_index", int(self.step_index))
        object.__setattr__(self, "dt", float(self.dt))

    def advance(self, dt: float | None = None) -> "SimulationClock":
        h = self.dt if dt is None else float(dt)
        if not math.isfinite(h) or h <= 0:
            raise ValueError("step dt must be finite and > 0")
        new_time = self.time + h
        if not math.isfinite(new_time) or new_time <= self.time:
            raise ValueError("clock advance must produce a finite strictly later time")
        return SimulationClock(new_time, self.step_index + 1, self.dt)


@dataclass(frozen=True)
class WorldObject:
    """Persistent world entity; intentionally physics-model agnostic."""
    object_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    kind: str = "object"
    position: np.ndarray = field(default_factory=lambda: np.zeros(3))
    velocity: np.ndarray = field(default_factory=lambda: np.zeros(3))
    state: Mapping[str, Any] = field(default_factory=dict)
    tags: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if not isinstance(self.object_id, str) or not self.object_id:
            raise ValueError("object_id must be a non-empty string")
        if not isinstance(self.kind, str) or not self.kind:
            raise ValueError("kind must be a non-empty string")
        object.__setattr__(self, "position", _finite_vec3(self.position, "position"))
        object.__setattr__(self, "velocity", _finite_vec3(self.velocity, "velocity"))
        clean_state = dict(self.state)
        clean_tags = tuple(str(t) for t in self.tags)
        object.__setattr__(self, "state", MappingProxyType(clean_state))
        object.__setattr__(self, "tags", clean_tags)

    def moved(self, position: Any, velocity: Any | None = None, **state_updates: Any) -> "WorldObject":
        state = dict(self.state)
        state.update(state_updates)
        return replace(self, position=position, velocity=self.velocity if velocity is None else velocity, state=state)


@dataclass(frozen=True)
class WorldEvent:
    """Immutable event in the world's event history."""
    event_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    time: float = 0.0
    event_type: str = "state_change"
    source_ids: tuple[str, ...] = ()
    target_ids: tuple[str, ...] = ()
    parent_event_ids: tuple[str, ...] = ()
    payload: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not math.isfinite(float(self.time)):
            raise ValueError("event time must be finite")
        if not self.event_type:
            raise ValueError("event_type must be non-empty")
        object.__setattr__(self, "time", float(self.time))
        object.__setattr__(self, "source_ids", tuple(str(x) for x in self.source_ids))
        object.__setattr__(self, "target_ids", tuple(str(x) for x in self.target_ids))
        object.__setattr__(self, "parent_event_ids", tuple(str(x) for x in self.parent_event_ids))
        object.__setattr__(self, "payload", MappingProxyType(dict(self.payload)))


@dataclass(frozen=True)
class EventLog:
    events: tuple[WorldEvent, ...] = ()

    def append(self, event: WorldEvent) -> "EventLog":
        if self.events and event.time < self.events[-1].time - _EPS:
            raise ValueError("events must be appended in non-decreasing time order")
        if any(e.event_id == event.event_id for e in self.events):
            raise ValueError("duplicate event_id")
        return EventLog(self.events + (event,))

    def since(self, time: float) -> tuple[WorldEvent, ...]:
        return tuple(e for e in self.events if e.time >= float(time))


@dataclass(frozen=True)
class CausalLedger:
    """Explicit directed event-dependency ledger."""
    parents: Mapping[str, tuple[str, ...]] = field(default_factory=dict)

    def __post_init__(self) -> None:
        clean = {str(k): tuple(str(v) for v in vals) for k, vals in self.parents.items()}
        for child, parent_ids in clean.items():
            if child in parent_ids:
                raise ValueError("causal self-loop is not allowed")
        object.__setattr__(self, "parents", MappingProxyType(clean))

    def add(self, event_id: str, parent_event_ids: tuple[str, ...] = ()) -> "CausalLedger":
        event_id = str(event_id)
        parent_event_ids = tuple(str(x) for x in parent_event_ids)
        if event_id in parent_event_ids:
            raise ValueError("causal self-loop is not allowed")
        if event_id in self.parents:
            raise ValueError("event already present in causal ledger")
        data = dict(self.parents)
        data[event_id] = parent_event_ids
        return CausalLedger(data)

    def ancestors(self, event_id: str) -> tuple[str, ...]:
        seen: set[str] = set()
        stack = list(self.parents.get(str(event_id), ()))
        while stack:
            current = stack.pop()
            if current in seen:
                continue
            seen.add(current)
            stack.extend(self.parents.get(current, ()))
        return tuple(sorted(seen))


@dataclass(frozen=True)
class LawRegistry:
    """Registry for immutable world-law identifiers and parameters."""
    laws: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)

    def __post_init__(self) -> None:
        clean: dict[str, Mapping[str, Any]] = {}
        for key, raw in self.laws.items():
            name = str(key)
            if not name:
                raise ValueError("law name must be non-empty")
            value = dict(raw)
            value.setdefault("version", "1.0")
            value.setdefault("domain", "universal")
            value.setdefault("invariants", ())
            if not isinstance(value["version"], str) or not value["version"]:
                raise ValueError("law version must be a non-empty string")
            if not isinstance(value["domain"], str) or not value["domain"]:
                raise ValueError("law domain must be a non-empty string")
            value["invariants"] = tuple(str(x) for x in value["invariants"])
            clean[name] = MappingProxyType(value)
        object.__setattr__(self, "laws", MappingProxyType(clean))

    def define(self, name: str, parameters: Mapping[str, Any] | None = None, *,
               version: str = "1.0", domain: str = "universal",
               invariants: tuple[str, ...] = ()) -> "LawRegistry":
        name = str(name)
        if not name or name in self.laws:
            raise ValueError("law name must be non-empty and unique")
        if not isinstance(version, str) or not version:
            raise ValueError("law version must be a non-empty string")
        if not isinstance(domain, str) or not domain:
            raise ValueError("law domain must be a non-empty string")
        data = dict(self.laws)
        entry = dict(parameters or {})
        entry.update({"version": version, "domain": domain, "invariants": tuple(invariants)})
        data[name] = entry
        return LawRegistry(data)

    def get(self, name: str) -> Mapping[str, Any]:
        return self.laws[str(name)]


@dataclass(frozen=True)
class WorldState:
    """Canonical immutable global world state."""
    identity: WorldIdentity
    space: Space3D
    clock: SimulationClock
    objects: Mapping[str, WorldObject] = field(default_factory=dict)
    laws: LawRegistry = field(default_factory=LawRegistry)
    events: EventLog = field(default_factory=EventLog)
    causality: CausalLedger = field(default_factory=CausalLedger)
    metadata: Mapping[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        self.space.validate()
        objects = {str(k): v for k, v in self.objects.items()}
        for key, obj in objects.items():
            if key != obj.object_id:
                raise ValueError("object mapping key must equal object_id")
            if not np.isfinite(obj.position).all() or not np.isfinite(obj.velocity).all():
                raise ValueError("world objects must have finite kinematics")
        event_ids = set()
        previous_time = -math.inf
        for event in self.events.events:
            if event.event_id in event_ids:
                raise ValueError("duplicate event_id")
            if event.time < previous_time - _EPS or event.time > self.clock.time + _EPS:
                raise ValueError("event time must be ordered and not exceed world time")
            event_ids.add(event.event_id)
            previous_time = event.time
        for event_id, parents in self.causality.parents.items():
            if event_id not in event_ids:
                raise ValueError("causal ledger references an unknown child event")
            if any(parent not in event_ids for parent in parents):
                raise ValueError("causal ledger references an unknown parent event")
        object.__setattr__(self, "objects", MappingProxyType(objects))
        object.__setattr__(self, "metadata", MappingProxyType(dict(self.metadata)))

    def add_object(self, obj: WorldObject) -> "WorldState":
        if obj.object_id in self.objects:
            raise ValueError(f"object already exists: {obj.object_id}")
        data = dict(self.objects)
        data[obj.object_id] = obj
        return replace(self, objects=data)

    def update_object(self, obj: WorldObject) -> "WorldState":
        if obj.object_id not in self.objects:
            raise KeyError(obj.object_id)
        data = dict(self.objects)
        data[obj.object_id] = obj
        return replace(self, objects=data)

    def remove_object(self, object_id: str) -> "WorldState":
        if object_id not in self.objects:
            raise KeyError(object_id)
        data = dict(self.objects)
        del data[object_id]
        return replace(self, objects=data)

    def state_digest(self) -> str:
        payload = {
            "world_id": self.identity.world_id,
            "parent_world_id": self.identity.parent_world_id,
            "seed": self.identity.seed,
            "space": {"origin": self.space.origin.tolist(),
                      "bounds_min": None if self.space.bounds_min is None else self.space.bounds_min.tolist(),
                      "bounds_max": None if self.space.bounds_max is None else self.space.bounds_max.tolist()},
            "clock": {"time": self.clock.time, "step": self.clock.step_index, "dt": self.clock.dt},
            "objects": [
                {
                    "id": o.object_id, "kind": o.kind,
                    "position": o.position.tolist(), "velocity": o.velocity.tolist(),
                    "state": dict(o.state), "tags": list(o.tags),
                }
                for o in sorted(self.objects.values(), key=lambda x: x.object_id)
            ],
            "laws": {k: dict(v) for k, v in sorted(self.laws.laws.items())},
            "causality": {k: list(v) for k, v in sorted(self.causality.parents.items())},
            "metadata": dict(self.metadata),
            "events": [
                {"id": e.event_id, "time": e.time, "type": e.event_type,
                 "source": list(e.source_ids), "target": list(e.target_ids),
                 "parents": list(e.parent_event_ids), "payload": dict(e.payload)}
                for e in self.events.events
            ],
        }
        raw = json.dumps(payload, sort_keys=True, separators=(",", ":"), default=str).encode()
        return hashlib.sha256(raw).hexdigest()


class WorldCore:
    """Controlled deterministic world-step engine for U0."""

    def __init__(self, state: WorldState):
        self._state = state

    @property
    def state(self) -> WorldState:
        return self._state

    def add_object(self, obj: WorldObject) -> WorldState:
        self._state = self._state.add_object(obj)
        return self._state

    def add_law(self, name: str, parameters: Mapping[str, Any] | None = None, *,
                version: str = "1.0", domain: str = "universal",
                invariants: tuple[str, ...] = ()) -> WorldState:
        self._state = replace(self._state, laws=self._state.laws.define(
            name, parameters, version=version, domain=domain, invariants=invariants))
        return self._state

    def emit(self, event_type: str, *, source_ids=(), target_ids=(), parent_event_ids=(), payload=None) -> WorldEvent:
        parent_event_ids = tuple(str(x) for x in parent_event_ids)
        known_events = {e.event_id for e in self._state.events.events}
        if any(parent not in known_events for parent in parent_event_ids):
            raise ValueError("all causal parents must already exist in the event history")
        event = WorldEvent(
            time=self._state.clock.time,
            event_type=event_type,
            source_ids=tuple(source_ids), target_ids=tuple(target_ids),
            parent_event_ids=tuple(parent_event_ids), payload=payload or {},
        )
        events = self._state.events.append(event)
        causal = self._state.causality.add(event.event_id, event.parent_event_ids)
        self._state = replace(self._state, events=events, causality=causal)
        return event

    def step(self, dt: float | None = None, updater: Callable[[WorldState, float], WorldState] | None = None) -> WorldState:
        h = self._state.clock.dt if dt is None else float(dt)
        if not math.isfinite(h) or h <= 0:
            raise ValueError("dt must be finite and > 0")
        current = self._state
        candidate = current if updater is None else updater(current, h)
        if not isinstance(candidate, WorldState):
            raise TypeError("world updater must return WorldState")
        # U0 owns the global clock: a physics/biology layer cannot silently alter it.
        candidate = replace(candidate, clock=current.clock.advance(h))
        if candidate.identity.world_id != current.identity.world_id:
            raise ValueError("world-step updater cannot silently replace world identity")
        if candidate.events.events and candidate.events.events[-1].time > candidate.clock.time + _EPS:
            raise ValueError("event time cannot exceed world time")
        # Re-run the state invariants after every world transition.
        candidate = WorldState(identity=candidate.identity, space=candidate.space, clock=candidate.clock,
                               objects=candidate.objects, laws=candidate.laws, events=candidate.events,
                               causality=candidate.causality, metadata=candidate.metadata)
        self._state = candidate
        return candidate

    def snapshot(self) -> WorldState:
        return self._state

aire/universe/chemistry.py:
"""AIRE U3 — deterministic chemistry layer.

U3 provides a conservative, solver-independent chemistry model suitable for
world-scale experiments. Concentrations are mol/m^3. Species carry molar mass
and charge metadata; reactions use integer stoichiometry and mass-action
kinetics. The implementation is intentionally not a quantum-chemistry or
high-fidelity molecular-dynamics solver.
"""
from __future__ import annotations
from dataclasses import dataclass, replace
import hashlib, math
from typing import Any, Mapping
import numpy as np

from .core import WorldCore, WorldState

U3_SCHEMA = "U3.1"
R_GAS = 8.31446261815324


def _field(a: Any, shape: tuple[int, ...], name: str) -> np.ndarray:
    x = np.asarray(a, dtype=float)
    if x.shape != shape or not np.all(np.isfinite(x)) or np.any(x < 0):
        raise ValueError(f"{name} must be finite and non-negative with shape {shape}")
    return x.copy()


@dataclass(frozen=True)
class ChemicalSpecies:
    name: str
    molar_mass: float
    charge: int = 0
    elements: Mapping[str, int] = None

    def __post_init__(self):
        if not isinstance(self.name, str) or not self.name:
            raise ValueError("species name must be non-empty")
        if not math.isfinite(self.molar_mass) or self.molar_mass <= 0:
            raise ValueError("molar_mass must be finite and > 0")
        if int(self.charge) != self.charge:
            raise ValueError("charge must be an integer")
        elems = {} if self.elements is None else {str(k): int(v) for k, v in self.elements.items()}
        if any(v <= 0 for v in elems.values()):
            raise ValueError("element counts must be positive integers")
        object.__setattr__(self, "charge", int(self.charge))
        object.__setattr__(self, "elements", elems)


@dataclass(frozen=True)
class ChemicalReaction:
    reaction_id: str
    reactants: Mapping[str, int]
    products: Mapping[str, int]
    rate_constant: float
    activation_energy: float = 0.0  # J/mol
    enthalpy: float = 0.0            # J/mol reaction extent; positive=endothermic
    reverse_rate_constant: float = 0.0
    catalysts: Mapping[str, int] = None
    equilibrium_constant: float | None = None

    def __post_init__(self):
        if not self.reaction_id:
            raise ValueError("reaction_id must be non-empty")
        r = {str(k): int(v) for k, v in self.reactants.items()}
        p = {str(k): int(v) for k, v in self.products.items()}
        if not r or not p or any(v <= 0 for v in (*r.values(), *p.values())):
            raise ValueError("reaction stoichiometry must use positive integers")
        if set(r) & set(p):
            raise ValueError("species cannot appear on both sides; use net stoichiometry")
        if not math.isfinite(self.rate_constant) or self.rate_constant < 0:
            raise ValueError("rate_constant must be finite and >= 0")
        if not math.isfinite(self.activation_energy) or self.activation_energy < 0:
            raise ValueError("activation_energy must be finite and >= 0")
        if not math.isfinite(self.enthalpy):
            raise ValueError("enthalpy must be finite")
        if not math.isfinite(self.reverse_rate_constant) or self.reverse_rate_constant < 0:
            raise ValueError("reverse_rate_constant must be finite and >= 0")
        cats = {} if self.catalysts is None else {str(k): int(v) for k, v in self.catalysts.items()}
        if any(v < 0 for v in cats.values()):
            raise ValueError("catalyst orders must be >= 0")
        if self.equilibrium_constant is not None and (not math.isfinite(self.equilibrium_constant) or self.equilibrium_constant <= 0):
            raise ValueError("equilibrium_constant must be finite and > 0")
        object.__setattr__(self, "reactants", r)
        object.__setattr__(self, "products", p)
        object.__setattr__(self, "catalysts", cats)

    def stoich(self, species: str) -> int:
        return self.products.get(species, 0) - self.reactants.get(species, 0)


@dataclass(frozen=True)
class ChemistryNetwork:
    species: Mapping[str, ChemicalSpecies]
    reactions: tuple[ChemicalReaction, ...] = ()

    def __post_init__(self):
        clean = {str(k): v for k, v in self.species.items()}
        if len(clean) != len(self.species):
            raise ValueError("duplicate species")
        for key, sp in clean.items():
            if key != sp.name:
                raise ValueError("species mapping key must equal species name")
        for rxn in self.reactions:
            unknown = (set(rxn.reactants) | set(rxn.products)) - set(clean)
            if unknown:
                raise ValueError(f"reaction references unknown species: {sorted(unknown)}")
        object.__setattr__(self, "species", clean)
        object.__setattr__(self, "reactions", tuple(self.reactions))

    @property
    def names(self) -> tuple[str, ...]:
        return tuple(sorted(self.species))

    def mass_balance(self, reaction: ChemicalReaction) -> float:
        return sum(reaction.stoich(n) * self.species[n].molar_mass for n in self.species)

    def charge_balance(self, reaction: ChemicalReaction) -> int:
        return sum(reaction.stoich(n) * self.species[n].charge for n in self.species)


@dataclass(frozen=True)
class ChemistryState:
    schema: str
    network: ChemistryNetwork
    concentrations: Mapping[str, np.ndarray]
    temperature: np.ndarray
    volume: float = 1.0
    time: float = 0.0
    heat_capacity: float = 1000.0

    def __post_init__(self):
        if self.schema != U3_SCHEMA:
            raise ValueError("unsupported chemistry schema")
        shape = np.asarray(self.temperature, dtype=float).shape
        if len(shape) != 2 or min(shape) < 1:
            raise ValueError("temperature must be a 2-D field")
        temp = _field(self.temperature, shape, "temperature")
        if np.any(temp <= 0):
            raise ValueError("temperature must be > 0")
        conc = {}
        for name in self.network.names:
            if name not in self.concentrations:
                raise ValueError(f"missing concentration field for {name}")
            conc[name] = _field(self.concentrations[name], shape, f"concentration[{name}]")
            conc[name].setflags(write=False)
        object.__setattr__(self, "concentrations", conc)
        temp.setflags(write=False); object.__setattr__(self, "temperature", temp)
        if not math.isfinite(self.volume) or self.volume <= 0:
            raise ValueError("volume must be finite and > 0")
        if not math.isfinite(self.time):
            raise ValueError("time must be finite")
        if not math.isfinite(self.heat_capacity) or self.heat_capacity <= 0:
            raise ValueError("heat_capacity must be finite and > 0")

    @property
    def shape(self): return self.temperature.shape

    def total_moles(self, species: str) -> float:
        return float(np.sum(self.concentrations[species]) * self.volume)

    def total_mass(self) -> float:
        return float(sum(self.total_moles(n) * self.network.species[n].molar_mass for n in self.network.names))

    def total_charge(self) -> float:
        return float(sum(self.total_moles(n) * self.network.species[n].charge for n in self.network.names))

    def digest(self) -> str:
        h = hashlib.sha256(); h.update(self.schema.encode()); h.update(repr(self.network).encode())
        h.update(np.ascontiguousarray(self.temperature).tobytes())
        for n in self.network.names: h.update(n.encode()); h.update(np.ascontiguousarray(self.concentrations[n]).tobytes())
        h.update(repr((self.volume, self.time, self.heat_capacity)).encode()); return h.hexdigest()


def _arrhenius(k0: float, activation_energy: float, temperature: np.ndarray) -> np.ndarray:
    if activation_energy == 0: return np.full_like(temperature, k0, dtype=float)
    exponent = np.clip(-activation_energy / (R_GAS * temperature), -700.0, 0.0)
    return k0 * np.exp(exponent)


def create_chemistry(network: ChemistryNetwork, temperature: Any = 298.15, *, shape=(8, 8), volume=1.0, time=0.0, concentrations=None) -> ChemistryState:
    temp = np.full(shape, float(temperature)) if np.isscalar(temperature) else np.asarray(temperature, dtype=float)
    concentrations = concentrations or {n: np.zeros(temp.shape, dtype=float) for n in network.names}
    return ChemistryState(U3_SCHEMA, network, concentrations, temp, volume, time, 1000.0)


def reaction_rates(state: ChemistryState) -> dict[str, np.ndarray]:
    rates = {}
    for rxn in state.network.reactions:
        rate = _arrhenius(rxn.rate_constant, rxn.activation_energy, state.temperature)
        for name, order in rxn.reactants.items(): rate = rate * np.power(state.concentrations[name], order)
        for name, order in rxn.catalysts.items(): rate = rate * np.power(state.concentrations[name], order)
        if rxn.reverse_rate_constant > 0:
            reverse = np.full(state.shape, rxn.reverse_rate_constant, dtype=float)
            for name, order in rxn.products.items(): reverse *= np.power(state.concentrations[name], order)
            for name, order in rxn.catalysts.items(): reverse *= np.power(state.concentrations[name], order)
            rate = rate - reverse
        rates[rxn.reaction_id] = rate
    return rates


def step_chemistry(state: ChemistryState, dt: float, *, diffusion: float = 0.0) -> tuple[ChemistryState, Mapping[str, Any]]:
    h = float(dt)
    if not math.isfinite(h) or h <= 0: raise ValueError("dt must be finite and > 0")
    if not 0 <= diffusion <= 1: raise ValueError("diffusion must be in [0,1]")
    conc = {n: state.concentrations[n].copy() for n in state.network.names}
    temp = state.temperature.copy(); rates = reaction_rates(state)
    reaction_extents = {}
    for rxn in state.network.reactions:
        r = rates[rxn.reaction_id]
        # Explicit Euler with a positivity-preserving extent limiter per cell.
        max_forward = np.full(state.shape, np.inf)
        for name, coeff in rxn.reactants.items():
            max_forward = np.minimum(max_forward, conc[name] / coeff)
        max_reverse = np.full(state.shape, np.inf)
        for name, coeff in rxn.products.items():
            max_reverse = np.minimum(max_reverse, conc[name] / coeff)
        raw = h * r
        extent = np.where(raw >= 0, np.minimum(raw, max_forward), -np.minimum(-raw, max_reverse))
        for name in rxn.reactants: conc[name] -= rxn.reactants[name] * extent
        for name in rxn.products: conc[name] += rxn.products[name] * extent
        if rxn.enthalpy != 0:
            # Approximate local thermal coupling. Positive enthalpy consumes heat.
            temp -= (rxn.enthalpy * extent) / state.heat_capacity
        reaction_extents[rxn.reaction_id] = float(np.sum(extent) * state.volume)
    if diffusion > 0:
        alpha = min(0.25, float(diffusion) * h)
        for n in conc:
            a = conc[n]
            conc[n] = np.maximum(0.0, (1-4*alpha)*a + alpha*(np.roll(a,1,0)+np.roll(a,-1,0)+np.roll(a,1,1)+np.roll(a,-1,1)))
    temp = np.maximum(1.0, temp)
    out = ChemistryState(U3_SCHEMA, state.network, conc, temp, state.volume, state.time+h)
    report = {
        "dt": h, "reaction_extents": reaction_extents,
        "mass_before": state.total_mass(), "mass_after": out.total_mass(),
        "charge_before": state.total_charge(), "charge_after": out.total_charge(),
        "temperature_min": float(np.min(out.temperature)), "digest": out.digest(),
    }
    report["mass_residual"] = report["mass_after"] - report["mass_before"]
    report["charge_residual"] = report["charge_after"] - report["charge_before"]
    report["certified_step"] = bool(abs(report["mass_residual"]) <= 1e-10 * max(1.0, abs(report["mass_before"])) and
                                      abs(report["charge_residual"]) <= 1e-10 * max(1.0, abs(report["charge_before"])))
    return out, report


def attach_chemistry(state: WorldState, chemistry: ChemistryState) -> WorldState:
    meta = dict(state.metadata)
    meta["u3_chemistry"] = {"schema": chemistry.schema, "species": list(chemistry.network.names),
                             "shape": list(chemistry.shape), "digest": chemistry.digest(), "time": chemistry.time}
    return replace(state, metadata=meta)


class ChemistryWorld:
    def __init__(self, core: WorldCore, chemistry: ChemistryState):
        if abs(chemistry.time - core.state.clock.time) > 1e-9: raise ValueError("chemistry time must match world clock")
        self.core, self.chemistry, self.last_report = core, chemistry, None
        self.core._state = attach_chemistry(core.state, chemistry)

    @property
    def state(self): return self.core.state

    def step(self, dt=None, *, diffusion=0.0):
        h = self.state.clock.dt if dt is None else float(dt)
        new, report = step_chemistry(self.chemistry, h, diffusion=diffusion)
        self.core.step(h, updater=lambda s, _h: attach_chemistry(s, new))
        self.chemistry, self.last_report = new, report
        return report

aire/universe/persistence.py:
"""AIRE UP — persistence, branching and deterministic replay.

UP adds an auditable persistence layer above the immutable U0 WorldState.  It
never mutates a historical checkpoint: branches are new world identities with
an explicit parent, and replay uses a serializable command log rather than
serializing executable callables.
"""
from __future__ import annotations

from dataclasses import dataclass, is_dataclass, asdict, replace
from typing import Any, Mapping
import copy
import json
import hashlib
from pathlib import Path
import numpy as np

from .core import (
    WorldCore, WorldEvent, WorldIdentity, WorldObject, WorldState,
    Space3D, SimulationClock, LawRegistry, EventLog, CausalLedger,
)

UP_SCHEMA = "UP.1"


def _encode(value: Any) -> Any:
    if isinstance(value, np.ndarray):
        return {"__type__": "ndarray", "dtype": str(value.dtype), "value": value.tolist()}
    if isinstance(value, np.generic):
        return value.item()
    if is_dataclass(value):
        return {"__type__": type(value).__name__, "value": {k: _encode(v) for k, v in asdict(value).items()}}
    if isinstance(value, Mapping):
        return {str(k): _encode(v) for k, v in value.items()}
    if isinstance(value, (tuple, list)):
        return [_encode(v) for v in value]
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    # U0 permits arbitrary state payloads, so persistence must fail closed
    # rather than silently producing a non-replayable representation.
    raise TypeError(f"non-persistable value: {type(value).__name__}")


def _decode_array(value: Any) -> Any:
    if isinstance(value, dict) and value.get("__type__") == "ndarray":
        return np.asarray(value["value"], dtype=value.get("dtype", "float64"))
    if isinstance(value, list):
        return [_decode_array(v) for v in value]
    if isinstance(value, dict):
        return {k: _decode_array(v) for k, v in value.items()}
    return value


def _object_to_dict(obj: WorldObject) -> dict[str, Any]:
    return {
        "object_id": obj.object_id,
        "kind": obj.kind,
        "position": _encode(obj.position),
        "velocity": _encode(obj.velocity),
        "state": _encode(dict(obj.state)),
        "tags": list(obj.tags),
    }


def _object_from_dict(data: Mapping[str, Any]) -> WorldObject:
    return WorldObject(
        object_id=str(data["object_id"]), kind=str(data["kind"]),
        position=_decode_array(data["position"]), velocity=_decode_array(data["velocity"]),
        state=_decode_array(data.get("state", {})), tags=tuple(data.get("tags", ())),
    )


def serialize_world(state: WorldState) -> dict[str, Any]:
    """Return a canonical, JSON-safe snapshot of a WorldState."""
    return {
        "schema": UP_SCHEMA,
        "identity": {
            "world_id": state.identity.world_id,
            "parent_world_id": state.identity.parent_world_id,
            "seed": state.identity.seed,
            "schema_version": state.identity.schema_version,
        },
        "space": {"origin": _encode(state.space.origin),
                  "bounds_min": _encode(state.space.bounds_min) if state.space.bounds_min is not None else None,
                  "bounds_max": _encode(state.space.bounds_max) if state.space.bounds_max is not None else None},
        "clock": {"time": state.clock.time, "step_index": state.clock.step_index, "dt": state.clock.dt},
        "objects": [_object_to_dict(o) for o in sorted(state.objects.values(), key=lambda x: x.object_id)],
        "laws": {k: _encode(dict(v)) for k, v in sorted(state.laws.laws.items())},
        "events": [{"event_id": e.event_id, "time": e.time, "event_type": e.event_type,
                    "source_ids": list(e.source_ids), "target_ids": list(e.target_ids),
                    "parent_event_ids": list(e.parent_event_ids), "payload": _encode(dict(e.payload))}
                   for e in state.events.events],
        "causality": {k: list(v) for k, v in sorted(state.causality.parents.items())},
        "metadata": _encode(dict(state.metadata)),
    }


def deserialize_world(data: Mapping[str, Any]) -> WorldState:
    if data.get("schema") != UP_SCHEMA:
        raise ValueError(f"unsupported world snapshot schema: {data.get('schema')!r}")
    ident = data["identity"]
    space = data["space"]
    clock = data["clock"]
    identity = WorldIdentity(**ident)
    world_space = Space3D(origin=_decode_array(space["origin"]),
                          bounds_min=_decode_array(space["bounds_min"]) if space["bounds_min"] is not None else None,
                          bounds_max=_decode_array(space["bounds_max"]) if space["bounds_max"] is not None else None)
    objects = {}
    for raw_obj in data.get("objects", []):
        obj = _object_from_dict(raw_obj)
        objects[obj.object_id] = obj
    events = tuple(WorldEvent(event_id=e["event_id"], time=e["time"], event_type=e["event_type"],
                              source_ids=tuple(e.get("source_ids", ())), target_ids=tuple(e.get("target_ids", ())),
                              parent_event_ids=tuple(e.get("parent_event_ids", ())),
                              payload=_decode_array(e.get("payload", {}))) for e in data.get("events", []))
    return WorldState(
        identity=identity, space=world_space,
        clock=SimulationClock(**clock), objects=objects,
        laws=LawRegistry(_decode_array(data.get("laws", {}))),
        events=EventLog(events),
        causality=CausalLedger({k: tuple(v) for k, v in data.get("causality", {}).items()}),
        metadata=_decode_array(data.get("metadata", {})),
    )


def canonical_world_json(state: WorldState) -> str:
    """Canonical JSON representation used for cross-run reproducibility."""
    return json.dumps(serialize_world(state), sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def compare_worlds(a: WorldState, b: WorldState) -> dict[str, Any]:
    """Return a deterministic, component-level first divergence report."""
    if a.state_digest() == b.state_digest():
        return {"equal": True, "first_divergence": None}
    sa, sb = serialize_world(a), serialize_world(b)
    for component in ("identity", "space", "clock", "objects", "laws", "events", "causality", "metadata"):
        if sa.get(component) != sb.get(component):
            return {
                "equal": False,
                "first_divergence": component,
                "left_digest": a.state_digest(),
                "right_digest": b.state_digest(),
            }
    return {"equal": False, "first_divergence": "digest_only", "left_digest": a.state_digest(), "right_digest": b.state_digest()}


def serialize_commands(commands: tuple["WorldCommand", ...] | list["WorldCommand"]) -> list[dict[str, Any]]:
    """Serialize a command log without executable code or callbacks."""
    return [{"sequence": int(c.sequence), "operation": c.operation, "payload": _encode(dict(c.payload))} for c in commands]


def deserialize_commands(data: list[Mapping[str, Any]]) -> tuple["WorldCommand", ...]:
    commands = tuple(WorldCommand(int(c["sequence"]), str(c["operation"]), _decode_array(c.get("payload", {}))) for c in data)
    expected = list(range(len(commands)))
    actual = [c.sequence for c in commands]
    if actual != expected:
        raise ValueError("command sequence is not contiguous")
    return commands


@dataclass(frozen=True)
class WorldCheckpoint:
    checkpoint_id: str
    world_digest: str
    state: Mapping[str, Any]
    schema: str = UP_SCHEMA

    @classmethod
    def capture(cls, world: WorldState, checkpoint_id: str) -> "WorldCheckpoint":
        payload = serialize_world(world)
        # The checkpoint integrity value is the canonical U0 world digest.
        # This makes restore verify semantic world state, not merely the JSON
        # container representation.
        digest = world.state_digest()
        return cls(str(checkpoint_id), digest, payload)

    def restore(self) -> WorldState:
        world = deserialize_world(copy.deepcopy(dict(self.state)))
        if world.state_digest() != self.world_digest:
            raise ValueError("checkpoint integrity digest mismatch")
        return world

    def save(self, path: str | Path) -> None:
        Path(path).write_text(json.dumps({"checkpoint_id": self.checkpoint_id,
                                          "world_digest": self.world_digest,
                                          "schema": self.schema,
                                          "state": self.state}, sort_keys=True, indent=2), encoding="utf-8")

    @classmethod
    def load(cls, path: str | Path) -> "WorldCheckpoint":
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        return cls(data["checkpoint_id"], data["world_digest"], data["state"], data.get("schema", UP_SCHEMA))


@dataclass(frozen=True)
class WorldCommand:
    sequence: int
    operation: str
    payload: Mapping[str, Any]


class WorldSession:
    """Command-recording facade for deterministic world experiments."""
    def __init__(self, initial: WorldState):
        self.core = WorldCore(initial)
        self.initial_snapshot = serialize_world(initial)
        self.commands: list[WorldCommand] = []

    @property
    def state(self) -> WorldState:
        return self.core.state

    def _record(self, operation: str, payload: Mapping[str, Any]) -> None:
        self.commands.append(WorldCommand(len(self.commands), operation, copy.deepcopy(dict(payload))))

    def add_object(self, obj: WorldObject) -> WorldState:
        self.core.add_object(obj)
        self._record("add_object", {"object": _object_to_dict(obj)})
        return self.state

    def update_object(self, obj: WorldObject) -> WorldState:
        self.core._state = self.core.state.update_object(obj)
        self._record("update_object", {"object": _object_to_dict(obj)})
        return self.state

    def remove_object(self, object_id: str) -> WorldState:
        self.core._state = self.core.state.remove_object(object_id)
        self._record("remove_object", {"object_id": str(object_id)})
        return self.state

    def emit(self, event_type: str, *, source_ids=(), target_ids=(), parent_event_ids=(), payload=None) -> WorldEvent:
        event = self.core.emit(event_type, source_ids=source_ids, target_ids=target_ids,
                               parent_event_ids=parent_event_ids, payload=payload)
        self._record("emit", {"event_id": event.event_id, "time": event.time, "event_type": event_type,
                               "source_ids": list(source_ids), "target_ids": list(target_ids),
                               "parent_event_ids": list(parent_event_ids), "payload": _encode(payload or {})})
        return event

    def step(self, dt: float | None = None) -> WorldState:
        h = self.state.clock.dt if dt is None else float(dt)
        self.core.step(h)
        self._record("step", {"dt": h})
        return self.state

    def checkpoint(self, checkpoint_id: str) -> WorldCheckpoint:
        return WorldCheckpoint.capture(self.state, checkpoint_id)

    def branch(self, branch_id: str, *, seed: int | None = None) -> "WorldSession":
        parent = self.state.identity.world_id
        identity = WorldIdentity(world_id=str(branch_id), parent_world_id=parent,
                                 seed=self.state.identity.seed if seed is None else int(seed),
                                 schema_version=self.state.identity.schema_version)
        child = deserialize_world(serialize_world(self.state))
        child = replace(child, identity=identity)
        return WorldSession(child)

    def replay(self) -> WorldState:
        return self.replay_from_commands(self.commands)

    def command_log_payload(self) -> list[dict[str, Any]]:
        return serialize_commands(self.commands)

    def save_command_log(self, path: str | Path) -> None:
        Path(path).write_text(json.dumps({
            "schema": UP_SCHEMA,
            "initial_snapshot": self.initial_snapshot,
            "commands": self.command_log_payload(),
        }, sort_keys=True, separators=(",", ":")), encoding="utf-8")

    @staticmethod
    def load_command_log(path: str | Path) -> tuple[dict[str, Any], tuple[WorldCommand, ...]]:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        if data.get("schema") != UP_SCHEMA:
            raise ValueError("unsupported command-log schema")
        return data["initial_snapshot"], deserialize_commands(data.get("commands", []))

    def replay_from_commands(self, commands: tuple[WorldCommand, ...] | list[WorldCommand]) -> WorldState:
        replay = WorldSession(deserialize_world(copy.deepcopy(self.initial_snapshot)))
        for cmd in deserialize_commands(serialize_commands(commands)):
            p = cmd.payload
            if cmd.operation == "add_object": replay.add_object(_object_from_dict(p["object"]))
            elif cmd.operation == "update_object": replay.update_object(_object_from_dict(p["object"]))
            elif cmd.operation == "remove_object": replay.remove_object(p["object_id"])
            elif cmd.operation == "emit":
                event = WorldEvent(event_id=p["event_id"], time=float(p["time"]), event_type=p["event_type"],
                                   source_ids=tuple(p["source_ids"]), target_ids=tuple(p["target_ids"]),
                                   parent_event_ids=tuple(p["parent_event_ids"]), payload=_decode_array(p["payload"]))
                replay.core._state = replace(replay.state,
                    events=replay.state.events.append(event),
                    causality=replay.state.causality.add(event.event_id, event.parent_event_ids))
            elif cmd.operation == "step": replay.step(p["dt"])
            else: raise ValueError(f"unknown replay operation: {cmd.operation}")
        return replay.state

    def branch_comparison(self, other: "WorldSession") -> dict[str, Any]:
        return compare_worlds(self.state, other.state)

    def command_log(self) -> tuple[WorldCommand, ...]:
        return tuple(self.commands)

aire/universe/energy.py:
"""AIRE cross-domain energy contract.

The world modules historically used different energy representations (Joules,
chemical enthalpy proxies, ATP units, ecological biomass units).  This module
introduces an explicit, auditable ledger without pretending those proxies are
physically equivalent until a conversion factor is declared.
"""
from __future__ import annotations
from dataclasses import dataclass
import hashlib, math
from typing import Mapping

_EPS = 1e-12

@dataclass(frozen=True)
class EnergyReservoir:
    reservoir_id: str
    amount_j: float
    capacity_j: float | None = None
    domain: str = "generic"
    def __post_init__(self):
        if not self.reservoir_id or not isinstance(self.reservoir_id, str):
            raise ValueError("reservoir_id must be non-empty")
        if not math.isfinite(self.amount_j) or self.amount_j < 0:
            raise ValueError("amount_j must be finite and >= 0")
        if self.capacity_j is not None and (not math.isfinite(self.capacity_j) or self.capacity_j <= 0):
            raise ValueError("capacity_j must be finite and > 0")
        if self.capacity_j is not None and self.amount_j > self.capacity_j + _EPS:
            raise ValueError("reservoir exceeds capacity")
        object.__setattr__(self, "domain", str(self.domain))

@dataclass(frozen=True)
class EnergyTransfer:
    transfer_id: str
    source: str
    target: str
    amount_j: float
    external_work_j: float = 0.0
    heat_loss_j: float = 0.0
    reason: str = "transfer"
    def __post_init__(self):
        if not self.transfer_id or not self.source or not self.target:
            raise ValueError("transfer/source/target identifiers must be non-empty")
        if self.source == self.target:
            raise ValueError("source and target must differ")
        for name in ("amount_j", "external_work_j", "heat_loss_j"):
            x = float(getattr(self, name))
            if not math.isfinite(x) or x < 0:
                raise ValueError(f"{name} must be finite and >= 0")

@dataclass(frozen=True)
class EnergyLedger:
    reservoirs: Mapping[str, EnergyReservoir]
    transfers: tuple[EnergyTransfer, ...] = ()
    external_input_j: float = 0.0
    external_output_j: float = 0.0

    def __post_init__(self):
        clean = {str(k): v for k, v in self.reservoirs.items()}
        if any(k != v.reservoir_id for k, v in clean.items()):
            raise ValueError("reservoir mapping key must equal reservoir_id")
        for name in ("external_input_j", "external_output_j"):
            x = float(getattr(self, name))
            if not math.isfinite(x) or x < 0:
                raise ValueError(f"{name} must be finite and >= 0")
        ids = set(clean)
        for t in self.transfers:
            if t.source not in ids or t.target not in ids:
                raise ValueError("transfer references unknown reservoir")
        object.__setattr__(self, "reservoirs", clean)
        object.__setattr__(self, "transfers", tuple(self.transfers))

    @property
    def total_stored_j(self) -> float:
        return float(sum(r.amount_j for r in self.reservoirs.values()))

    @property
    def total_heat_loss_j(self) -> float:
        return float(sum(t.heat_loss_j for t in self.transfers))

    @property
    def total_external_work_j(self) -> float:
        return float(sum(t.external_work_j for t in self.transfers))

    @property
    def balance_residual_j(self) -> float:
        """Stored change against declared external inputs/outputs and losses.

        A closed ledger has residual zero.  Transfers between internal
        reservoirs cancel exactly and therefore cannot create energy.
        """
        return self.total_stored_j + self.external_output_j + self.total_heat_loss_j + self.total_external_work_j - self.external_input_j

    def digest(self) -> str:
        h = hashlib.sha256(); h.update(b"AIRE-ENERGY-1")
        for rid in sorted(self.reservoirs):
            r = self.reservoirs[rid]
            h.update(repr((r.reservoir_id, r.amount_j, r.capacity_j, r.domain)).encode())
        for t in self.transfers:
            h.update(repr((t.transfer_id, t.source, t.target, t.amount_j, t.external_work_j, t.heat_loss_j, t.reason)).encode())
        h.update(repr((self.external_input_j, self.external_output_j)).encode())
        return h.hexdigest()

    def assert_balanced(self, before_stored_j: float, *, external_input_j: float = 0.0,
                        external_output_j: float = 0.0, heat_loss_j: float = 0.0,
                        external_work_j: float = 0.0, atol: float = 1e-9) -> float:
        before = float(before_stored_j)
        for x in (before, external_input_j, external_output_j, heat_loss_j, external_work_j):
            if not math.isfinite(x) or x < 0:
                raise ValueError("energy balance inputs must be finite and >= 0")
        residual = self.total_stored_j - before - external_input_j + external_output_j + heat_loss_j + external_work_j
        scale = max(1.0, abs(before), self.total_stored_j, abs(external_input_j))
        if abs(residual) > atol * scale:
            raise ValueError(f"energy ledger not balanced: residual={residual}")
        return float(residual)

aire/universe/ecology.py:
"""AIRE U5 — deterministic mesoscopic ecology.

U5 adds population/resource dynamics above U4 physiology. It models bounded
resource pools, organism populations, reproduction, mortality, competition and
predation using deterministic rate equations. It intentionally does not model
individual cognition, genetics or agent behaviour; those belong to U6-U9.
"""
from __future__ import annotations

from dataclasses import dataclass
import hashlib
import math
from typing import Any, Mapping

from .core import WorldCore, WorldState

U5_SCHEMA = "U5.1"


def _nn(x: float, name: str) -> float:
    x = float(x)
    if not math.isfinite(x) or x < 0:
        raise ValueError(f"{name} must be finite and >= 0")
    return x


def _frac(x: float, name: str) -> float:
    x = float(x)
    if not math.isfinite(x) or x < 0 or x > 1:
        raise ValueError(f"{name} must be finite and in [0,1]")
    return x


@dataclass(frozen=True)
class EcologicalResource:
    resource_id: str
    amount: float
    regeneration_rate: float = 0.0
    carrying_capacity: float = 1.0

    def __post_init__(self):
        if not self.resource_id:
            raise ValueError("resource_id must be non-empty")
        _nn(self.amount, "amount")
        _nn(self.regeneration_rate, "regeneration_rate")
        _nn(self.carrying_capacity, "carrying_capacity")
        if self.carrying_capacity <= 0:
            raise ValueError("carrying_capacity must be > 0")

    def digest(self) -> str:
        return hashlib.sha256(repr((self.resource_id, self.amount,
                                    self.regeneration_rate,
                                    self.carrying_capacity)).encode()).hexdigest()


@dataclass(frozen=True)
class EcologicalPopulation:
    population_id: str
    size: float
    biomass: float = 1.0
    resource: str | None = None
    consumption_rate: float = 0.0
    reproduction_rate: float = 0.0
    mortality_rate: float = 0.0
    carrying_capacity: float = 1e9
    resource_efficiency: float = 1.0
    predation_loss_rate: float = 0.0
    thermal_tolerance: tuple[float, float] = (250.0, 330.0)

    def __post_init__(self):
        if not self.population_id:
            raise ValueError("population_id must be non-empty")
        _nn(self.size, "size")
        _nn(self.biomass, "biomass")
        for n in ("consumption_rate", "reproduction_rate", "mortality_rate",
                  "resource_efficiency", "predation_loss_rate"):
            _nn(getattr(self, n), n)
        _nn(self.carrying_capacity, "carrying_capacity")
        if self.carrying_capacity <= 0:
            raise ValueError("carrying_capacity must be > 0")
        lo, hi = self.thermal_tolerance
        if not (math.isfinite(lo) and math.isfinite(hi) and lo <= hi):
            raise ValueError("thermal_tolerance must be finite and ordered")

    def digest(self) -> str:
        return hashlib.sha256(repr((self.population_id, self.size, self.biomass,
                                    self.resource, self.consumption_rate,
                                    self.reproduction_rate, self.mortality_rate,
                                    self.carrying_capacity, self.resource_efficiency,
                                    self.predation_loss_rate,
                                    self.thermal_tolerance)).encode()).hexdigest()


@dataclass(frozen=True)
class PredationLink:
    predator_id: str
    prey_id: str
    rate: float
    efficiency: float = 0.5

    def __post_init__(self):
        if not self.predator_id or not self.prey_id or self.predator_id == self.prey_id:
            raise ValueError("predator and prey ids must be distinct and non-empty")
        _nn(self.rate, "rate")
        _frac(self.efficiency, "efficiency")


@dataclass(frozen=True)
class EcologyState:
    schema: str
    resources: Mapping[str, EcologicalResource]
    populations: Mapping[str, EcologicalPopulation]
    predation: tuple[PredationLink, ...] = ()
    time: float = 0.0

    def __post_init__(self):
        if self.schema != U5_SCHEMA:
            raise ValueError("unsupported ecology schema")
        r = {str(k): v for k, v in self.resources.items()}
        p = {str(k): v for k, v in self.populations.items()}
        if any(k != v.resource_id for k, v in r.items()):
            raise ValueError("resource mapping key must equal resource_id")
        if any(k != v.population_id for k, v in p.items()):
            raise ValueError("population mapping key must equal population_id")
        if not math.isfinite(float(self.time)) or self.time < 0:
            raise ValueError("time must be finite and >= 0")
        object.__setattr__(self, "resources", r)
        object.__setattr__(self, "populations", p)
        object.__setattr__(self, "predation", tuple(self.predation))
        object.__setattr__(self, "time", float(self.time))

    @property
    def total_population(self) -> float:
        return float(sum(p.size for p in self.populations.values()))

    @property
    def total_resource(self) -> float:
        return float(sum(r.amount for r in self.resources.values()))

    def digest(self) -> str:
        h = hashlib.sha256(); h.update(self.schema.encode()); h.update(repr(self.time).encode())
        for rid in sorted(self.resources):
            h.update(rid.encode()); h.update(self.resources[rid].digest().encode())
        for pid in sorted(self.populations):
            h.update(pid.encode()); h.update(self.populations[pid].digest().encode())
        for link in sorted(self.predation, key=lambda x: (x.predator_id, x.prey_id)):
            h.update(repr(link).encode())
        return h.hexdigest()


def create_ecology(resources: Mapping[str, EcologicalResource] | None = None,
                   populations: Mapping[str, EcologicalPopulation] | None = None,
                   predation: tuple[PredationLink, ...] = (), *, time: float = 0.0) -> EcologyState:
    return EcologyState(U5_SCHEMA, resources or {}, populations or {}, predation, time)


def step_ecology(state: EcologyState, dt: float) -> tuple[EcologyState, Mapping[str, Any]]:
    h = float(dt)
    if not math.isfinite(h) or h <= 0:
        raise ValueError("dt must be finite and > 0")
    # Deterministic sub-stepping protects explicit rate equations from very large dt.
    n = max(1, int(math.ceil(h / 1.0)))
    sh = h / n
    resources = dict(state.resources)
    populations = dict(state.populations)
    total_consumed = total_regenerated = total_births = total_deaths = total_predation = 0.0

    for _ in range(n):
        # Resource regeneration is logistic and bounded by carrying capacity.
        for rid, r in list(resources.items()):
            growth = r.regeneration_rate * r.amount * max(0.0, 1.0 - r.amount / r.carrying_capacity)
            amount = min(r.carrying_capacity, max(0.0, r.amount + growth * sh))
            total_regenerated += max(0.0, amount - r.amount)
            resources[rid] = EcologicalResource(rid, amount, r.regeneration_rate, r.carrying_capacity)

        consumption_by_pop: dict[str, float] = {rid: 0.0 for rid in resources}
        births: dict[str, float] = {}
        deaths: dict[str, float] = {}
        predation_loss: dict[str, float] = {pid: 0.0 for pid in populations}

        for link in state.predation:
            predator = populations.get(link.predator_id)
            prey = populations.get(link.prey_id)
            if predator is None or prey is None:
                continue
            eaten = min(prey.size, link.rate * predator.size * sh)
            predation_loss[prey.population_id] += eaten
            births[link.predator_id] = births.get(link.predator_id, 0.0) + eaten * link.efficiency
            total_predation += eaten

        for pid, p in populations.items():
            resource_amount = resources[p.resource].amount if p.resource in resources else 0.0
            desired = p.consumption_rate * p.size * sh
            consumed = min(resource_amount, desired)
            if p.resource in consumption_by_pop:
                consumption_by_pop[p.resource] += consumed
            else:
                consumed = 0.0
            # Resource availability controls reproduction; carrying capacity adds density dependence.
            food_factor = 0.0 if desired <= 0 else consumed / desired
            density_factor = max(0.0, 1.0 - p.size / p.carrying_capacity)
            temp_factor = 1.0
            # Ecology state is deliberately environment-agnostic; tolerance is used only
            # if a future environment handoff provides temperature in metadata.
            births[pid] = births.get(pid, 0.0) + p.reproduction_rate * p.size * food_factor * density_factor * sh
            deaths[pid] = deaths.get(pid, 0.0) + p.mortality_rate * p.size * sh + predation_loss.get(pid, 0.0)

        for rid, consumed in consumption_by_pop.items():
            r = resources[rid]
            actual = min(r.amount, max(0.0, consumed))
            resources[rid] = EcologicalResource(rid, r.amount - actual, r.regeneration_rate, r.carrying_capacity)
            total_consumed += actual

        for pid, p in populations.items():
            b = births.get(pid, 0.0)
            d = min(p.size + b, deaths.get(pid, 0.0))
            size = max(0.0, min(p.carrying_capacity, p.size + b - d))
            # Biomass tracks population size and cannot become negative.
            biomass = max(0.0, p.biomass * (size / p.size) if p.size > 0 else size)
            populations[pid] = EcologicalPopulation(
                pid, size, biomass, p.resource, p.consumption_rate,
                p.reproduction_rate, p.mortality_rate, p.carrying_capacity,
                p.resource_efficiency, p.predation_loss_rate, p.thermal_tolerance)
            total_births += b
            total_deaths += d

    new = EcologyState(U5_SCHEMA, resources, populations, state.predation, state.time + h)
    report = {
        "dt": h,
        "resource_before": state.total_resource,
        "resource_after": new.total_resource,
        "population_before": state.total_population,
        "population_after": new.total_population,
        "resource_consumed": total_consumed,
        "resource_regenerated": total_regenerated,
        "births": total_births,
        "deaths": total_deaths,
        "predation": total_predation,
        "nonnegative": all(r.amount >= 0 for r in new.resources.values()) and all(p.size >= 0 for p in new.populations.values()),
        "bounded_resources": all(r.amount <= r.carrying_capacity + 1e-12 for r in new.resources.values()),
        "bounded_populations": all(p.size <= p.carrying_capacity + 1e-12 for p in new.populations.values()),
        "finite": all(math.isfinite(r.amount) for r in new.resources.values()) and all(math.isfinite(p.size) for p in new.populations.values()),
        "digest": new.digest(),
    }
    report["certified_step"] = bool(report["nonnegative"] and report["bounded_resources"] and report["bounded_populations"] and report["finite"])
    return new, report


def attach_ecology(state: WorldState, ecology: EcologyState) -> WorldState:
    meta = dict(state.metadata)
    meta["u5_ecology"] = {
        "schema": ecology.schema,
        "resources": sorted(ecology.resources),
        "populations": sorted(ecology.populations),
        "time": ecology.time,
        "digest": ecology.digest(),
    }
    return state.__class__(state.identity, state.space, state.clock, state.objects, state.laws,
                           state.events, state.causality, meta)


class EcologyWorld:
    """World-Core handoff for deterministic population ecology."""
    def __init__(self, core: WorldCore, ecology: EcologyState):
        if abs(ecology.time - core.state.clock.time) > 1e-9:
            raise ValueError("ecology time must match world clock")
        self.core, self.ecology, self.last_report = core, ecology, None
        self.core._state = attach_ecology(core.state, ecology)

    @property
    def state(self) -> WorldState:
        return self.core.state

    def step(self, dt: float | None = None):
        h = self.state.clock.dt if dt is None else float(dt)
        new, report = step_ecology(self.ecology, h)
        self.core.step(h, updater=lambda s, _h: attach_ecology(s, new))
        self.ecology, self.last_report = new, report
        self.core.emit("ecology_step", payload={"dt": h, "certified": report["certified_step"], "ecology_digest": new.digest()})
        return report

