import json, base64
from pathlib import Path
from aire.alpha_world import AlphaWorld, create_alpha_world
from aire.universe.agent import ACTION_NAMES, action_command
WORLD=None; SEED=20260815; DT=1.0; GRID=(8,8)
def _new():
    global WORLD
    WORLD=create_alpha_world(seed=SEED,dt=DT,grid=GRID); return _status()
def init():
    if WORLD is None: _new()
    return _j(_status())
def _status():
    w=WORLD; f=w.organism.functional; s=w.organism.sensors; a=w.autonomy
    objs=[{"id":o.object_id,"x":float(o.position[0]),"y":float(o.position[1]),"z":float(o.position[2]),"held":bool(o.held)} for o in (w.material_objects or [])]
    return {"time":float(w.time),"step":int(w.core.state.clock.step_index),"alive":bool(w.organism.alive),
      "autonomous":bool(w.autonomous),"action":(ACTION_NAMES[a.last_action] if a.last_action is not None else "—"),
      "reward":float(a.last_reward),"cumulative_reward":float(a.cumulative_reward),"epsilon":float(a.epsilon),
      "memory":len(a.memory),"autobiography":len(a.autobiography),"digest":w.digest(),
      "position":[float(x) for x in w.organism.position],"velocity":[float(x) for x in w.organism.velocity],
      "sensors":{"temperature":float(s.temperature),"pressure":float(s.pressure),"oxygen":float(s.oxygen),
        "water":float(s.water),"nutrient":float(s.nutrient),"light":float(s.light),"contact":float(s.contact)},
      "physiology":{"core_temperature":float(f.core_temperature),"hydration":float(f.hydration),
        "fatigue":float(f.fatigue),"pain":float(f.pain),"balance":float(f.balance),"heart_rate":float(f.heart_rate)},
      "objects":objs}
def _j(x): return json.dumps(x,ensure_ascii=False,separators=(",",":"))
def status(): return _j(_status())
def step(count=1,action=None):
    count=max(1,min(int(count),1000))
    for _ in range(count):
        if not WORLD.organism.alive: break
        if action:
            if action not in ACTION_NAMES: raise ValueError("Unknown action")
            if action in ("push","grasp","release"):
                WORLD._material_action(action); cmd=action_command(0,WORLD.autonomy_config)
            else: cmd=action_command(ACTION_NAMES.index(action),WORLD.autonomy_config)
            WORLD.step(command=cmd,compute_digest=False)
        else: WORLD.step(compute_digest=False)
    return _j(_status())
def set_autonomous(enabled):
    WORLD.autonomous=bool(enabled); return _j(_status())
def reset(): return _new() and _j(_status())
def checkpoint():
    p=Path("/aire_checkpoint.bin"); WORLD.save_checkpoint(p); return base64.b64encode(p.read_bytes()).decode("ascii")
def restore(encoded):
    global WORLD
    p=Path("/aire_checkpoint.bin"); p.write_bytes(base64.b64decode(encoded)); WORLD=AlphaWorld.load_checkpoint(p); return _j(_status())
